INSERT INTO `product` (`heritage_id`, `name`, `description`, `price`, `original_price`, `stock`, `images`, `specs`, `category`, `seller`, `sales`, `rating`, `tags`, `status`) VALUES
(1, '青花瓷茶杯', '景德镇手工青花瓷茶杯，采用传统手工制瓷工艺，以优质高岭土为原料，由非遗传承人亲自绘制青花纹饰。白如玉、明如镜，茶汤映衬下青花更显典雅。', 168.00, 228.00, 100, '/uploads/images/products/青花瓷茶杯.jpg', '{"规格":["单杯（含礼盒）","对杯（含礼盒）","四杯套装（含茶盘）"],"价格":{"单杯（含礼盒）":168,"对杯（含礼盒）":298,"四杯套装（含茶盘）":528}}', '陶瓷', '景德镇古窑瓷庄', 256, 4.8, '景德镇,青花瓷,茶杯,手工', 1),
(1, '粉彩花瓶', '景德镇粉彩花瓶，采用粉彩装饰技法，画面细腻柔美、色彩丰富典雅。器型端庄秀丽，适合家居陈设或送礼佳选。历经72道工序、1300度高温烧制而成。', 368.00, 498.00, 50, '/uploads/images/products/粉彩花瓶.jpg', '{"规格":["18cm赏瓶","25cm梅瓶","35cm天球瓶"],"价格":{"18cm赏瓶":368,"25cm梅瓶":568,"35cm天球瓶":888}}', '陶瓷', '景德镇古窑瓷庄', 128, 4.9, '景德镇,粉彩,花瓶,陈设瓷', 1),
(8, '吉州窑木叶盏', '宋代吉州窑经典木叶天目盏复刻版。取天然桑叶，经特殊工艺处理后置于盏中，在高温下一次烧成。叶片脉络清晰可见，如浮于盏中，每片叶子独一无二。', 258.00, 328.00, 80, '/uploads/images/products/吉州窑木叶盏.jpg', '{"规格":["标准盏（口径8cm）","大盏（口径10cm）"],"价格":{"标准盏（口径8cm）":258,"大盏（口径10cm）":358}}', '陶瓷', '吉州窑陶瓷研究所', 185, 4.7, '吉州窑,木叶盏,天目,茶器', 1),
(10, '婺源绿茶礼盒', '精选婺源高山茶区明前嫩芽，由非遗传承人严格按照传统制茶技艺手工炒制。外形紧细翠绿、汤色清澈明亮、香气高长持久、滋味鲜爽醇厚。', 128.00, 168.00, 200, '/uploads/images/products/婺源绿茶礼盒.jpg', '{"规格":["250g尝鲜装","500g精品礼盒","1000g家庭装"],"价格":{"250g尝鲜装":128,"500g精品礼盒":228,"1000g家庭装":388}}', '茶叶', '婺源绿茶合作社', 320, 4.9, '婺源绿茶,明前茶,高山茶,礼盒', 1),
(14, '夏布绣屏风', '新余夏布绣手工屏风，以手工苎麻夏布为底，采用平针、乱针等多种针法绣制。夏布粗犷的质感与精细的绣线形成独特对比，古朴典雅。', 588.00, 788.00, 30, '/uploads/images/products/夏布绣屏风.jpg', '{"规格":["小号（30×40cm）","中号（50×60cm）","大号（80×100cm）"],"价格":{"小号（30×40cm）":588,"中号（50×60cm）":888,"大号（80×100cm）":1288}}', '刺绣', '新余夏布绣研究院', 68, 4.8, '夏布绣,屏风,刺绣,手工', 1),
(13, '瓷板画挂饰', '南昌瓷板画手工挂饰，以瓷板为纸、矿物颜料为墨，经800度高温烧制而成。色彩鲜艳、永不褪色。', 428.00, 568.00, 40, '/uploads/images/products/瓷板画挂饰.jpg', '{"规格":["圆形（直径20cm）","方形（25×25cm）","扇形（30×40cm）"],"价格":{"圆形（直径20cm）":428,"方形（25×25cm）":568,"扇形（30×40cm）":788}}', '美术', '南昌瓷板画艺术中心', 96, 4.6, '瓷板画,挂饰,南昌,传统美术', 1),
(9, '连四纸信笺', '铅山连四纸手工信笺，采用古法72道工序精制而成。纸质洁白如玉、薄而坚韧、吸水性强、防虫耐藏。', 68.00, 88.00, 150, '/uploads/images/products/连四纸信笺.jpg', '{"规格":["素色信笺（50张）","印花信笺（30张）","精品礼盒套装"],"价格":{"素色信笺（50张）":68,"印花信笺（30张）":88,"精品礼盒套装":188}}', '文房', '铅山连四纸坊', 210, 4.7, '连四纸,信笺,文房,手工纸', 1),
(15, '瑞昌剪纸摆件', '瑞昌民间剪纸艺人手工剪制，不描不画、一气呵成。线条流畅自然、虚实相生。外框采用实木装裱，既可悬挂装饰，也可桌面摆放。', 88.00, 118.00, 120, '/uploads/images/products/瑞昌剪纸摆件.jpg', '{"规格":["小号（20×20cm）","中号（30×30cm）","大号（40×40cm）"],"价格":{"小号（20×20cm）":88,"中号（30×30cm）":128,"大号（40×40cm）":188}}', '美术', '瑞昌剪纸工作室', 168, 4.5, '瑞昌剪纸,摆件,手工,民间艺术', 1),
(3, '傩面具挂件', '以南丰跳傩面具为原型手工缩小复刻，采用传统木雕工艺精雕细琢，彩绘用矿物颜料色泽浓郁。傩面具是傩文化之魂，寓意驱邪纳福。', 128.00, 158.00, 90, '/uploads/images/products/傩面具挂件.jpg', '{"规格":["开山（驱邪）","傩公（福寿）","傩婆（吉祥）","雷公（镇宅）"],"价格":{"开山（驱邪）":128,"傩公（福寿）":128,"傩婆（吉祥）":128,"雷公（镇宅）":128}}', '文创', '南丰傩文化传习所', 145, 4.8, '傩面具,挂件,南丰,驱邪纳福', 1),
(16, '全丰花灯摆件', '以修水全丰花灯为原型手工制作的精美摆件，采用传统竹编骨架和丝绸裱糊工艺，造型精巧、色彩艳丽。', 198.00, 258.00, 60, '/uploads/images/products/全丰花灯摆件.jpg', '{"规格":["鲤鱼灯（好运）","荷花灯（和美）","龙凤灯（喜庆）"],"价格":{"鲤鱼灯（好运）":198,"荷花灯（和美）":198,"龙凤灯（喜庆）":258}}', '文创', '全丰花灯传承基地', 78, 4.6, '全丰花灯,摆件,修水,民俗', 1);
